using System;
using UnityEngine.SceneManagement;

namespace ScalingLaws.Core
{
    /// <summary>
    /// Scene names and the handful of flags that survive a scene load. Both scenes are generated by
    /// the editor builder, so these names are the contract between the builder and the runtime and
    /// must not drift apart.
    /// </summary>
    public static class SceneFlow
    {
        public const string MainMenuScene = "MainMenu";
        public const string GameScene = "Game";
        public const string CityScene = "City";

        /// <summary>
        /// Set by the menu before loading the game scene. True resumes the stored campaign, false
        /// starts a fresh one. A static flag because it is the only thing that has to cross a scene
        /// boundary, and a whole persistent object for one boolean is not worth it.
        /// </summary>
        public static bool ResumeSavedCampaign { get; set; }

        /// <summary>Company name typed on the menu, used only when starting fresh.</summary>
        public static string RequestedCompanyName { get; set; } = "Prometheus AI";

        /// <summary>
        /// Where the company is, as an office tier (0 is the founder's house). Set by the office
        /// just before the city loads, so the map opens on the building the player just left rather
        /// than on the house they moved out of. An int because `Core` does not know the catalog.
        /// </summary>
        public static int MapHomeOffice { get; set; }

        /// <summary>
        /// A `MapSiteCatalog` id the map should open on instead of the company's own address.
        ///
        /// Set by a news story carrying a venue, cleared by the map on the way in. The same
        /// hand-off `MapHomeOffice` already uses, rather than a second way to carry a request
        /// across a scene load.
        /// </summary>
        public static string MapFocusSite { get; set; } = string.Empty;

        /// <summary>
        /// A `MapSiteCatalog` id whose stand window the company should open on the way back.
        ///
        /// **The same hand-off as `MapFocusSite`, in the other direction.** A news story carrying
        /// a venue sends the map somewhere; pressing the book button on the map sends the player
        /// back to the desk with that venue's stand window open.
        ///
        /// It is a request rather than a purchase, and that is deliberate: the city scene has no
        /// reference to the company at all, by design, because `Core` may not know `Simulation`.
        /// Carrying the company into the map to sell one stand would be a second place money
        /// moves. The decision stays on the one screen that already makes it.
        ///
        /// A string, like `MapFocusSite`, because `Core` does not know the catalogues.
        /// </summary>
        public static string StandRequestSite { get; set; } = string.Empty;

        /// <summary>Which opening tile was chosen. Read once by the game scene.</summary>
        public static int RequestedArchetype { get; set; }

        /// <summary>The two founder traits picked, as enum values.</summary>
        public static int RequestedTraitA { get; set; }

        public static int RequestedTraitB { get; set; }

        /// <summary>What the founder is called. Carried into the campaign, never into the save key.</summary>
        /// <summary>
        /// What the player typed at the creator, or nothing.
        ///
        /// **Empty rather than "Anonymous".** That word used to be the default here and the default
        /// in the field, and a playtest found their own product page signed by it. The interface
        /// decides what a blank name looks like; see `UiFormat.PersonName`.
        /// </summary>
        public static string RequestedFounderName { get; set; } = string.Empty;

        /// <summary>Skill levels chosen at creation, in catalog order. Empty means every default.</summary>
        public static int[] RequestedSkillLevels { get; set; } = Array.Empty<int>();

        /// <summary>
        /// Which model the founder is, by prefab name.
        ///
        /// A name rather than an index, because dropping another character pack into the project
        /// renumbers everybody and an index would quietly turn an existing founder into a stranger.
        /// Empty means whichever comes first, which is what a campaign started before this existed
        /// gets.
        /// </summary>
        public static string RequestedFounderLook { get; set; } = string.Empty;

        /// <summary>Zero is bare-faced. One upward are the pairs of glasses that were found.</summary>
        public static int RequestedFounderGlasses { get; set; }

        /// <summary>
        /// DEBUG MODE was on when the campaign was started: every node researched, the bank full,
        /// and no achievements for any of it.
        ///
        /// Read once by the game scene, like every other request here, and then it belongs to
        /// `CompanyState.IsSandbox`, which is saved. A flag that lived only here would be lost the
        /// first time the campaign was reloaded, and the reload would earn achievements.
        /// </summary>
        public static bool RequestedDebugMode { get; set; }

        /// <summary>
        /// Start the campaign with the tour already behind it.
        ///
        /// **Only offered to somebody who has started a campaign on this machine before.** A first
        /// run has nothing to skip past yet, and a new player who takes the offer is alone in a
        /// game with fifteen tabs. Set by the creator, read once by the shell, and never written
        /// into a save: what it does is move the guide to its finished stage, which the save
        /// already carries.
        /// </summary>
        public static bool RequestedSkipTutorial { get; set; }

        /// <summary>Where the company registers. Zero means the default, America.</summary>
        public static int RequestedRegion { get; set; }

        /// <summary>The country inside that region. Zero means the region's first entry.</summary>
        public static int RequestedCountry { get; set; }

        /// <summary>
        /// The trait a company of the player's own brings, standing in for a named lab's house
        /// trait. Zero, meaning `FounderTrait.None`, for every preset archetype.
        /// </summary>
        public static int RequestedCompanyTrait { get; set; }

        /// <summary>
        /// Where the player left the opening trade, in dollars. Zero means they never touched it
        /// and the company opens on the default, which is the position the whole game is balanced
        /// against.
        /// </summary>
        public static long RequestedOpeningCashUsd { get; set; }

        /// <summary>
        /// The chosen company mark, by name. Empty falls back to the first, which is also what a
        /// name this build does not ship falls back to.
        /// </summary>
        public static string RequestedCompanyLogo { get; set; } = string.Empty;

        /// <summary>Starts a campaign from the opening flow rather than from defaults.</summary>
        public static void StartNewCampaign(string companyName, int archetype, int traitA, int traitB)
        {
            RequestedArchetype = archetype;
            RequestedTraitA = traitA;
            RequestedTraitB = traitB;
            StartNewCampaign(companyName);
        }

        public static void LoadMainMenu()
        {
            SceneManager.LoadScene(MainMenuScene);
        }

        public static void StartNewCampaign(string companyName)
        {
            ResumeSavedCampaign = false;
            RequestedCompanyName = string.IsNullOrWhiteSpace(companyName) ? "Prometheus AI" : companyName.Trim();
            SceneManager.LoadScene(GameScene);
        }

        public static void ResumeCampaign()
        {
            ResumeSavedCampaign = true;
            SceneManager.LoadScene(GameScene);
        }

        /// <summary>
        /// The founder reached the car. The caller has already saved, so there is nothing here to
        /// carry across but the request itself — everything <see cref="CityScene"/> needs to look
        /// right (districts, roads, pins, the legend) already lives in that scene, not in memory.
        /// </summary>
        public static void OpenCityMap()
        {
            SceneManager.LoadScene(CityScene);
        }

        /// <summary>
        /// Leaving the map the same way every other return to the campaign works: resume the save
        /// just written, rather than inventing a second path back into <see cref="GameScene"/> that
        /// carries state through memory instead of through the slot both paths already trust.
        /// </summary>
        public static void ReturnFromCityMap()
        {
            ResumeSavedCampaign = true;
            SceneManager.LoadScene(GameScene);
        }
    }
}
